HC = ((1, 1, 2), (1, 2, 2), (2, 2, 3), (2, 3, 3), (3, 3, 4))
HZ = ((0, 1, 1), (1, 1, 2), (1, 1, 2), (1, 2, 2), (1, 2, 2))


def generate(seed):
    r = random.Random(seed)
    z = r.random() < 0.12                               # 12 % of pyramids have nothing tipping
    R = 6
    for _ in range(500):
        B = r.choice((11, 12, 12, 13))
        G = [[1] * B]
        for k in range(1, R):
            m = B - k
            row = [1] * m
            h = r.choice((HZ if z else HC)[k - 1])
            while h:
                j = r.randrange(m)
                if row[j]:
                    row[j] = 0                          # a cup somebody has taken away
                    h -= 1
            G.append(row)
        for k in range(1, R):
            a, b = G[k], G[k - 1]
            for j in range(B - k):
                if a[j] and not (b[j] or b[j + 1]):
                    a[j] = 0                            # nothing at all underneath: it cannot be there
        cnt = [sum(row) for row in G]
        if any(cnt[k] > cnt[k - 1] or not cnt[k] for k in range(1, R)):
            continue                                    # a pyramid is never wider higher up
        holes = R * B - R * (R - 1) // 2 - sum(cnt)
        if holes < 3:
            continue
        tips, weigh = [], []                            # every precarious cup stands beside a gap below
        for k in range(R - 1):
            b, a = G[k], G[k + 1]
            u = G[k + 2] if k + 2 < R else []
            m = len(u)
            for x in range(B - k):
                if b[x]:
                    continue
                for j, d in ((x, 0), (x - 1, 1)):
                    if 0 <= j < B - k - 1 and a[j] and (b[j] if d else b[j + 1]):
                        if (0 < j <= m and u[j - 1]) or (j < m and u[j]):
                            weigh.append((k + 1, j))    # one support gone but weighed down: it stays
                        else:
                            tips.append((k + 1, j, d))
        n = len(tips)
        if (n == 0) != z or n > 7 or len(weigh) < 2:
            continue
        if n and not [1 for k, _, _ in tips if k < R - 1]:
            continue                                    # not every tipping cup is in the top row
        if n > 1 and len({d for _, _, d in tips}) < 2:
            continue                                    # one demo must show both directions
        if len({(k - 1, j + d) for k, j, d in tips}) != n:
            continue                                    # two cups may not tip into the same gap
        if n:                                           # a cup a CHAIN would take next, and we do not:
            S = {(k, j) for k, j, _ in tips}            # precarious, and every cup on top of it tips away
            if not [1 for k, j in weigh
                    if not [1 for y in (j - 1, j) if 0 <= y < B - k - 1 and G[k + 1][y] and (k + 1, y) not in S]]:
                continue
        for k, j, d in tips:                            # no row of the ANSWER may come out empty
            cnt[k] -= 1
            cnt[k - 1] += 1
        if not all(cnt):
            continue
        free = 0                                        # cups on two supports, nothing on top, gap beside
        for k in range(1, R):
            b, a = G[k - 1], G[k]
            u = G[k + 1] if k + 1 < R else []
            m = len(u)
            for x in range(B - k):
                if a[x]:
                    continue
                for j in (x - 1, x + 1):
                    if 0 <= j < B - k and a[j] and b[j] and b[j + 1] \
                            and not ((0 < j <= m and u[j - 1]) or (j < m and u[j])):
                        free += 1
        if free < 2:
            continue
        loose = sum(1 for k in range(R - 1) for j in range(B - k) if G[k][j]
                    and not ((j and G[k + 1][j - 1]) or (j < B - k - 1 and G[k + 1][j]))) + sum(G[R - 1])
        T = cnt[R - 1] + len([1 for k, _, _ in tips if k == R - 1])
        if n in (holes, loose, T, len(G[R - 1]) - T, sum(map(sum, G))):
            continue
        W = 4 * B
        P = [[" "] * W for _ in range(R)]
        for k in range(R):
            for j in range(B - k):
                if G[k][j]:
                    c = 2 * k + 4 * j
                    P[R - 1 - k][c:c + 4] = "\\__/"
        return "\n".join("".join(x).rstrip() for x in P) + "\n" + "=" * W + "\n" + str(n) + " tip"
    return FB

