def solve(clue):
    *P, E, T = clue.split("\n")
    W = len(E)
    B = W // 4
    R = len(P)
    P = [x.ljust(W) for x in P]
    q = lambda k, j: 0 <= k < R and 0 <= j < B - k and P[R - 1 - k][2 * k + 4 * j] == "\\"
    O = [[" "] * W for _ in range(R)]
    for k in range(R):
        for j in range(B - k):
            if not q(k, j):
                continue
            L, M = q(k - 1, j), q(k - 1, j + 1)
            if k and L != M and not (q(k + 1, j - 1) or q(k + 1, j)):
                x = 2 * k - 2 + 4 * (j + int(L))
                O[R - k][x:x + 4] = "|__>" if L else "<__|"
            else:
                x = 2 * k + 4 * j
                O[R - 1 - k][x:x + 4] = "\\__/"
    return "\n".join("".join(x).rstrip() for x in O) + "\n" + E + "\n" + T

